      if(!on){ if((g.userData.litOff = (g.userData.litOff || 0) + 1) > 30) LIT.delete(g); continue; }   // (gone from the scene: let it go)
      g.userData.litOff = 0;
      const L = g.userData.lit, u = L.u, mat = g.userData.spriteMat;
