        u.uLitDir.value[n].copy(_lv);
        const e = g.userData.litEcl, red = g.userData.litRed;
        if(e < 1 && red){                                    // the Moon in Earth's shadow: dim and coppery
          u.uLitCol.value[n].set(S.c[0]*k*(e + (1 - e)*0.5), S.c[1]*k*(e + (1 - e)*0.15), S.c[2]*k*(e + (1 - e)*0.06));
        } else u.uLitCol.value[n].set(S.c[0]*k*e, S.c[1]*k*e, S.c[2]*k*e);
        n++;
