      u.uLitN.value = n; u.uLitAmb.value = _lsrcN ? LIT_AMBIENT : LIT_FALLBACK;
      _shS.setFromMatrixScale(g.matrixWorld);                // (its disc, for its shadows: centre and radius in the camera's frame)
