  // J2000 equatorial -> native galactic (IAU). Game frames:
  //  'gal': procedural modes + Universe tiers 1-5; +x toward the galactic centre, +y north galactic
  //         pole (same mapping as galToVec / eqToVec).
  //  'ecl': Earth mode + Universe tier 0; planets orbit in XZ moving +x -> +z, so ecliptic longitude
  //         runs +x -> +z and ecliptic north is -y. The zodiac lines up with the planets' plane.
  const M_GAL = [[-0.0548755604,-0.8734370902,-0.4838350155],[0.4941094279,-0.4448296300,0.7469822445],[-0.8676661490,-0.1980763734,0.4559837762]];
  const OBLIQUITY = 23.4393*Math.PI/180;
  const EQ_TO_GAL = [M_GAL[0], M_GAL[2], M_GAL[1].map(v=>-v)];
  const EQ_TO_ECL = [[1,0,0],[0,Math.sin(OBLIQUITY),-Math.cos(OBLIQUITY)],[0,Math.cos(OBLIQUITY),Math.sin(OBLIQUITY)]];
  function mat3T(m){ return [[m[0][0],m[1][0],m[2][0]],[m[0][1],m[1][1],m[2][1]],[m[0][2],m[1][2],m[2][2]]]; }
  function mat3Mul(a,b){ return a.map(r=>[0,1,2].map(j=>r[0]*b[0][j]+r[1]*b[1][j]+r[2]*b[2][j])); }
  function mat3Apply(m,v){ const x=v.x,y=v.y,z=v.z; return v.set(m[0][0]*x+m[0][1]*y+m[0][2]*z, m[1][0]*x+m[1][1]*y+m[1][2]*z, m[2][0]*x+m[2][1]*y+m[2][2]*z); }
  function quatFromMat3(m){
    const m11=m[0][0],m12=m[0][1],m13=m[0][2],m21=m[1][0],m22=m[1][1],m23=m[1][2],m31=m[2][0],m32=m[2][1],m33=m[2][2];
    const tr = m11+m22+m33;
    if(tr > 0){ const s = 0.5/Math.sqrt(tr+1); return {w:0.25/s, x:(m32-m23)*s, y:(m13-m31)*s, z:(m21-m12)*s}; }
    if(m11 > m22 && m11 > m33){ const s = 2*Math.sqrt(1+m11-m22-m33); return {w:(m32-m23)/s, x:0.25*s, y:(m12+m21)/s, z:(m13+m31)/s}; }
    if(m22 > m33){ const s = 2*Math.sqrt(1+m22-m11-m33); return {w:(m13-m31)/s, x:(m12+m21)/s, y:0.25*s, z:(m23+m32)/s}; }
    const s = 2*Math.sqrt(1+m33-m11-m22); return {w:(m21-m12)/s, x:(m13+m31)/s, y:(m23+m32)/s, z:0.25*s};
  }
  const GAL_NATIVE_TO_EQ = mat3T(M_GAL);
  const ECL_TO_GAL = mat3Mul(EQ_TO_GAL, mat3T(EQ_TO_ECL));   // game-ecliptic -> game-galactic
  const GAL_TO_ECL = mat3T(ECL_TO_GAL);
  const SKY_QUAT = { gal: quatFromMat3(EQ_TO_GAL), ecl: quatFromMat3(EQ_TO_ECL) };
  const SKY_R = 1000;   // sky sphere radius before scaling; setSky() parks it just inside the far plane
  // B-V colour index -> RGB (blue-white O/B stars through orange-red M giants)
  const BV_TABLE = [[-0.4,0.61,0.69,1.00],[-0.2,0.67,0.75,1.00],[0.0,0.79,0.84,1.00],[0.3,0.97,0.97,1.00],
                    [0.6,1.00,0.96,0.92],[0.9,1.00,0.90,0.77],[1.2,1.00,0.82,0.63],[1.5,1.00,0.75,0.50],[2.0,1.00,0.63,0.35]];
  function bvColor(bv, out){
    if(bv <= BV_TABLE[0][0]){ out[0]=BV_TABLE[0][1]; out[1]=BV_TABLE[0][2]; out[2]=BV_TABLE[0][3]; return out; }
    for(let i=1;i<BV_TABLE.length;i++){
      if(bv <= BV_TABLE[i][0]){
        const a = BV_TABLE[i-1], b = BV_TABLE[i], t = (bv-a[0])/(b[0]-a[0]);
        out[0]=a[1]+(b[1]-a[1])*t; out[1]=a[2]+(b[2]-a[2])*t; out[2]=a[3]+(b[3]-a[3])*t; return out;
      }
    }
    const z = BV_TABLE[BV_TABLE.length-1]; out[0]=z[1]; out[1]=z[2]; out[2]=z[3]; return out;
  }
  const starfield = (function makeStarfield(){
    const group = new THREE.Group();
    // one Points per brightness band (PointsMaterial has a single size); sizes are screen pixels
    const BANDS = [[0.5,6.2],[1.5,5.0],[2.5,4.0],[3.5,3.2],[4.5,2.6],[5.5,2.1],[99,1.8]];
    const bins = BANDS.map(()=>({P:[], C:[]}));
    const col = [0,0,0];
    function addStar(x, y, z, mag, r, g, b, k){
      let i = 0; while(mag > BANDS[i][0]) i++;
      if(k === undefined) k = clamp(1.12 - 0.14*(mag+1), 0.22, 1);
      bins[i].P.push(x*SKY_R, y*SKY_R, z*SKY_R);
      bins[i].C.push(r*k, g*k, b*k);
    }
    // 1) the real catalog
    for(let i=0;i<BRIGHT_STARS.length;i+=4){
      const ra = BRIGHT_STARS[i]*Math.PI/12, de = BRIGHT_STARS[i+1]*Math.PI/180;
      bvColor(BRIGHT_STARS[i+3], col);
      addStar(Math.cos(de)*Math.cos(ra), Math.cos(de)*Math.sin(ra), Math.sin(de), BRIGHT_STARS[i+2], col[0], col[1], col[2]);
    }
    const rng = mulberry32(20260924);
    const gn = ()=>Math.sqrt(-2*Math.log(1 - rng()*0.999999))*Math.cos(2*Math.PI*rng());
    const v = new THREE.Vector3();
    function galDeg(lDeg, bDeg){ const l = lDeg*Math.PI/180, b = bDeg*Math.PI/180; return v.set(Math.cos(b)*Math.cos(l), Math.cos(b)*Math.sin(l), Math.sin(b)); }
    function toEq(){ return mat3Apply(GAL_NATIVE_TO_EQ, v); }
    // 2) faint naked-eye stars, mag 4.5-6.5: count rises ~3x per magnitude, denser near the galactic plane
    const K = 0.48*Math.LN10;
    for(let n=0; n<3800; ){
      v.set(gn(), gn(), gn()).normalize();                    // uniform direction, native galactic
      const bDeg = Math.asin(v.z)*180/Math.PI;
      if(rng() > 0.35 + 0.65*Math.exp(-(bDeg/18)*(bDeg/18))) continue;
      const mag = 4.5 + Math.log(1 + rng()*(Math.exp(2*K)-1))/K;
      bvColor(-0.25 + rng()*1.75, col);
      toEq(); addStar(v.x, v.y, v.z, mag, col[0], col[1], col[2]);
      n++;
    }
    // 3) Milky Way glow: thousands of very dim points hugging the galactic plane, brightest and
    //    thickest toward the centre (Sagittarius), split by the Great Rift from Cygnus to Sagittarius
    for(let n=0; n<11000; ){
      const l = rng()*360, dl = Math.min(l, 360-l);
      if(rng() > 0.35 + 0.65*Math.exp(-(dl/60)*(dl/60))) continue;
      const sig = 2.5 + 3.5*Math.exp(-(dl/35)*(dl/35));
      const b = gn()*sig;
      if((l < 70 || l > 340) && Math.abs(b - 0.5) < 1.3 && rng() < 0.8) continue;   // Great Rift dust lane
      const warm = Math.exp(-(dl/50)*(dl/50));
      galDeg(l, b); toEq();
      addStar(v.x, v.y, v.z, 99, 0.86 + 0.14*warm, 0.9 + 0.05*warm, 1.0 - 0.12*warm, 0.1 + 0.12*warm);
      n++;
    }
    // 4) naked-eye galaxies as faint smudges: the Magellanic Clouds and Andromeda
    const smudge = (l0, b0, sl, sb, count, k)=>{
      for(let n=0;n<count;n++){ const b = b0 + gn()*sb; galDeg(l0 + gn()*sl/Math.cos(b*Math.PI/180), b); toEq(); addStar(v.x, v.y, v.z, 99, 0.92, 0.92, 1.0, k); }
    };
    smudge(280.47, -32.89, 3.2, 2.2, 900, 0.14);   // Large Magellanic Cloud
    smudge(302.80, -44.30, 1.5, 1.0, 380, 0.13);   // Small Magellanic Cloud
    smudge(121.17, -21.57, 1.0, 0.35, 120, 0.12);  // Andromeda
    BANDS.forEach((band, i)=>{
      const bin = bins[i];
      if(!bin.P.length) return;
      const geo = new THREE.BufferGeometry();
      geo.setAttribute('position', new THREE.BufferAttribute(new Float32Array(bin.P), 3));
      geo.setAttribute('color', new THREE.BufferAttribute(new Float32Array(bin.C), 3));
      const mat = new THREE.PointsMaterial({map: STARFIELD_POINT_TEXTURE, size: band[1], sizeAttenuation:false, vertexColors:true,
        transparent:true, depthWrite:false, blending:THREE.AdditiveBlending, fog:false});
      const pts = new THREE.Points(geo, mat);
      pts.renderOrder = -10;      // true background: drawn before every other transparent object
      pts.frustumCulled = false;
      group.add(pts);
    });
    scene.add(group);
    return group;
  })();
  // orient the sky for the current frame and park it just inside the far plane, so real geometry
  // (planets, the Sun) always sits in front of it
  function setSky(frame){
    const q = SKY_QUAT[frame];
    starfield.quaternion.set(q.x, q.y, q.z, q.w);
    starfield.scale.setScalar(camera.far*0.9/SKY_R);
  }

  // ---------- world config ----------
  const CHUNK_SIZE = 50;
  const LOAD_RADIUS = 1;

  const GROWTH_PER_MASS = 0.009; // radius ∝ mass, like a real Schwarzschild radius — linear, uncapped (was 0.006: too slow)
  const G_CONST = 45;
  const G_SOFTENING = 1.2;
  const G_BODY = 20;         // gravity strength for non-black hole bodies (stars, planets, etc.)
  const UP_HINT = new THREE.Vector3(0,1,0);
  const RIGHT_HINT = new THREE.Vector3(1,0,0);
  const BODY_GRAVITY_RANGE = 38;
  const GIANT_CHANCE = 0.0005;      // rare supermassive-variant trigger, shared across the extreme and large tiers
  const MAX_RIVAL_BLACKHOLES = 2;   // global cap, independent of chunk loading — not counting the player's own
  const EXTREME_TYPES = new Set(['blackhole']); // the largest things the universe can produce
  const LARGE_TYPES = new Set(['quasar']); // varied and sometimes huge, but capped well under the extreme tier
  const EXTREME_GIANT_MIN = 25, EXTREME_GIANT_MAX = 400;
  const LARGE_GIANT_MIN = 8, LARGE_GIANT_MAX = 90;
  // explicit typical-size ranges (radius units) — quasar and blackhole are not
  // listed here and keep their existing formula-based generation untouched
  const SIZE_RANGES = {
    asteroid: [0.5, 1.2],
    comet: [0.2, 0.4],
    planet: [0.6, 1.4],
    junk: [0.2, 0.5],
    star: [0.6, 1.6],
  };
  const STAR_SUPERGIANT_CHANCE = 0.0002; // 0.02%
  const STAR_SUPERGIANT_SIZE = 8;
  const MAX_OBJECT_SIZE = 400; // hard ceiling regardless of any multiplier stacking

  // "value" = mass contributed to the black hole's own growth/score if fully absorbed.
  // "density" = used only for how strongly a body pulls smaller things around it —
  // a loose, gameplay-flavored stand-in for real astrophysical density (e.g. galaxies
  // are mostly empty space so they're rated low-density despite being huge).
  const TYPES = {
    asteroid: { size:0.85, value:1,    color:0x8a8496, rare:1.0,    density:2.5 },
    comet:    { size:0.3,  value:3,    color:0x7fd8ff, rare:0.55,   density:0.5 },
    junk:     { size:0.35, value:1,    color:0x9a9aa2, rare:0.35,   density:3.0 }, // small manufactured debris/wreckage
    moon:     { size:0.42, value:6,    color:0xb8b0c4, rare:0,      density:2.8 }, // only spawns orbiting planets, never as an independent chunk roll
    planet:   { size:1.0,  value:15,   color:0xe8a35c, rare:0.22,   density:3.5 },
    star:     { size:1.1,  value:40,   color:0xfff2b0, rare:0.10,   density:9 },
    violetdwarf: { size:0.22, value:55, color:0xcfe0ff, rare:0.05,  density:32 }, // a neutron star (key kept): tiny, super dense
    blackhole:{ size:0.95, value:300,  color:0xff5d5d, rare:0.02,   density:11 },
    quasar:   { size:1.9,  value:600,  color:0xbfe6ff, rare:0.008,  density:30 },
    whitehole:{ size:1.0,  value:350,  color:0xffffff, rare:0,      density:8 }, // disabled for now — pushes things away instead of pulling them in
    universe: { size:1.8,  value:1000, color:0xffc46a, rare:0.004,  density:15 },   // an ultramassive black hole (key kept)
  };
  const TOTAL_RARE = Object.values(TYPES).reduce((s,t)=>s+t.rare,0);
  const OBJECTS_PER_CHUNK = 6;
