  const PLANET_BOOST_COLOR = 0x2dffe0;
  const BELT_CHANCE = 0.25;       // chance a spawned planet/star gets an asteroid belt
  const MOON_CHANCE = 0.3;        // chance a spawned planet gets 1-3 moons
  const NEBULA_CHANCE = 0.12;     // chance a chunk has a decorative gas cloud
  // Suns, quasars and black holes all absorb and grow, but at different rates —
  // black holes grow fastest, then quasars, then suns slowest. Violet dwarfs are
  // suns too, for hierarchy purposes.
  const GROWTH_RATE = { star:0.0012, violetdwarf:0.0012, quasar:0.0028, blackhole:0.004 };
  const SUN_TYPES = new Set(['star','violetdwarf']);
  const COLLISION_TYPES = new Set(['planet','comet','asteroid','moon','junk']); // "regular" bodies that can crash into each other
