  function buildNeighbourhood(g){
    const sunCol = SPECTRAL.G;
    g.add(makeBodyGlow(sunCol, 1.6*2));
    addMarker(g, ORIGIN3, sunCol, 0.02, 'Sun — you are here', '#ffe9a8');
    for(const st of NB_STARS){
      const col = SPECTRAL[st.cls];
      const body = makeBodyGlow(col, 1.6*Math.sqrt(st.rad)*2); body.position.copy(st.center); g.add(body);
      const glow = makeGlow(col, st.rad > 1.5 ? 0.02 : 0.013); glow.position.copy(st.center); g.add(glow);
      const lab = makeLabel(st.name + ' · ' + st.dist.toFixed(st.dist < 10 ? 2 : 1) + ' ly'); lab.position.copy(st.center); g.add(lab);
      setBodyMass(st.name, starMass(st.name, st.cls));
      if(g === uGroup) addGrav(st.center, starMass(st.name, st.cls), Math.max(1.6*Math.sqrt(st.rad), st.enterR), st.name, false);   // (soft by the time you're in)
      regBody(st.name, 'star', st.size1, body, (dispose)=>{
        for(const o of [glow, lab]){ g.remove(o); disposeUniverseObj(o); }
        g.remove(body);
        if(dispose) disposeUniverseObj(body); else scene.add(body);
      });
    }
    if(tierAvatar() && gameMode !== 'passive') buildRogues(g);
  }
