  // Every Local Group galaxy's tier-3 placement and how close you must fly to enter it. A galaxy whose
  // centre sits inside a bigger one's entry sphere (M32/M110 in Andromeda, the Sagittarius Dwarf in the
  // Milky Way) can't be entered on its own: it appears as a satellite inside its host instead.
  const MW_CENTRE_HELIO_LY = new THREE.Vector3(26000, 0, 0);   // Sun -> galactic centre (+x)
  const LG_BODIES = LOCAL_GALAXIES.map(([name, l, b, d, rLy, type, inc])=>{
    const helioLy = galToVec(l, b, d);
    const center = helioLy.clone().multiplyScalar(1e-4).add(SUN_T3);
    const R = rLy/1e4;
    const los = helioLy.clone().normalize();
    const perp = new THREE.Vector3().crossVectors(los, UP_AXIS).normalize();
    const incR = inc*Math.PI/180;
    const normal = los.clone().multiplyScalar(Math.cos(incR)).addScaledVector(perp, Math.sin(incR));
    return { name, d, rLy, type, helioLy, center, R, normal, enterR: Math.max(R*0.9, 0.5), lyPerUnit: rLy/1000 };
  });
