  function hashSeed(str){ let h = 2166136261; for(let i=0;i<str.length;i++){ h ^= str.charCodeAt(i); h = Math.imul(h, 16777619); } return h >>> 0; }
  // smaller galaxies within reach of the host, drawn at their real offsets (host centre = origin)
  function addSatellites(grp, hostHelioLy, lyPerUnit, hostName, rng){
    const reach = U_TIERS[GALAXY_TIER].exitR*0.95*lyPerUnit;
    for(const sb of LG_BODIES){
      if(sb.name === hostName) continue;
      const rel = sb.helioLy.clone().sub(hostHelioLy);
      if(rel.length() > reach) continue;
      const c = rel.multiplyScalar(1/lyPerUnit), R = sb.rLy/lyPerUnit, look = TYPE_LOOK[sb.type];
      // same particles-per-area as the host disc (26,000 over a 1000-unit disc), so a satellite reads
      // as a faint companion rather than a dense blob brighter than the galaxy around it
      const count = Math.round(clamp(26000/(Math.PI*1000*1000) * Math.PI*R*R * 1.5, 60, 1500));
      grp.add(galaxyCloud(rng, { type:sb.type, count, radius:R, arms: sb.type === 'spiral' ? 2 : 0,
        pitchDeg:16, bulgeFrac:0.22, thick:0.02, flat:look.flat, size:Math.max(1.5, R*0.02), opacity:0.85, center:c, normal:sb.normal,
        armColor:look.armColor, bulgeColor:look.bulgeColor }));
      addMarker(grp, c, 0xe8e0ff, 0.012, sb.name + ' · satellite');
    }
  }
