  // ---------- comet tails: streams of particles ----------
  // Each tail is shed by the nucleus as it goes. Dust leaves with the comet's own velocity and then feels
  // the Sun's gravity weakened by the push of sunlight (radiation pressure, beta 0.1-0.6), so it drifts
  // onto slightly different orbits and falls behind: the dust tail curves back along the comet's path, and
  // bends hardest where the orbit turns sharply, around perihelion. Ions are blown almost straight out by
  // the solar wind, so that tail stays nearly straight, bending a little with the comet's own motion.
  const TAIL_N_DUST = 720, TAIL_N_ION = 420, TAIL_N = TAIL_N_DUST + TAIL_N_ION;
  const TAIL_VERT = `
    attribute float aSize; attribute float aAlpha; attribute vec3 aColor;
    uniform float uScale; varying vec3 vColor; varying float vAlpha;
    void main(){
      vColor = aColor; vAlpha = aAlpha;
      vec4 mv = modelViewMatrix*vec4(position, 1.0);
      gl_Position = projectionMatrix*mv;
      gl_PointSize = aAlpha > 0.0 ? clamp(aSize*uScale/max(-mv.z, 1e-4), 1.5, 48.0) : 0.0;
    }`;
  const TAIL_FRAG = `
    varying vec3 vColor; varying float vAlpha;
    void main(){
      vec2 d = gl_PointCoord - 0.5; float r2 = dot(d, d);
      if(r2 > 0.25 || vAlpha <= 0.003) discard;
      gl_FragColor = vec4(vColor, exp(-r2*14.0)*vAlpha);
    }`;
  function makeCometTail(){
    const geo = new THREE.BufferGeometry();
    const P = new Float32Array(TAIL_N*3), C = new Float32Array(TAIL_N*3), S = new Float32Array(TAIL_N), A = new Float32Array(TAIL_N);
    geo.setAttribute('position', new THREE.BufferAttribute(P, 3));
    geo.setAttribute('aColor', new THREE.BufferAttribute(C, 3));
    geo.setAttribute('aSize', new THREE.BufferAttribute(S, 1));
    geo.setAttribute('aAlpha', new THREE.BufferAttribute(A, 1));
    const mat = new THREE.ShaderMaterial({ uniforms:{ uScale:{ value:600 } }, vertexShader:TAIL_VERT, fragmentShader:TAIL_FRAG,
      transparent:true, depthWrite:false, blending:THREE.AdditiveBlending });
    const points = new THREE.Points(geo, mat); points.frustumCulled = false;
    return { points, geo, P, C, S, A, V:new Float32Array(TAIL_N*3), age:new Float32Array(TAIL_N), life:new Float32Array(TAIL_N),
      beta:new Float32Array(TAIL_N), bright:new Float32Array(TAIL_N), nextDust:0, nextIon:TAIL_N_DUST, accDust:0, accIon:0 };
  }
  function spawnTailParticle(T, k, ion, p, vel, anti, act){
    const j = k*3, R = Math.random;
    T.P[j] = p.x + (R() - 0.5)*0.06; T.P[j+1] = p.y + (R() - 0.5)*0.06; T.P[j+2] = p.z + (R() - 0.5)*0.06;
    if(!ion){
      // dust: the comet's own motion, a gentle push away from the Sun, a little spread
      T.V[j] = vel.x + anti.x*3 + (R() - 0.5)*0.5; T.V[j+1] = vel.y + anti.y*3 + (R() - 0.5)*0.5; T.V[j+2] = vel.z + anti.z*3 + (R() - 0.5)*0.5;
      T.beta[k] = 0.15 + 0.6*R(); T.life[k] = 4 + 3*R(); T.bright[k] = (0.3 + 0.2*R())*Math.min(1, 0.45 + act);
      const w = 0.85 + 0.15*R(); T.C[j] = w; T.C[j+1] = 0.92*w; T.C[j+2] = 0.76*w;
    } else {
      // ions: blown out by the solar wind, nearly straight away from the Sun
      const sw = 30 + 15*R();
      T.V[j] = vel.x*0.3 + anti.x*sw + (R() - 0.5)*1.2; T.V[j+1] = vel.y*0.3 + anti.y*sw + (R() - 0.5)*1.2; T.V[j+2] = vel.z*0.3 + anti.z*sw + (R() - 0.5)*1.2;
      T.beta[k] = 0; T.life[k] = 0.8 + 0.6*R(); T.bright[k] = (0.5 + 0.22*R())*Math.min(1, 0.45 + act);
      T.C[j] = 0.5; T.C[j+1] = 0.76; T.C[j+2] = 1;
    }
    T.age[k] = 0;
  }
  function updateCometTail(T, p, vel, act, dt){
    if(dt <= 0) return;
    const anti = cTmpC.copy(p).normalize();
    let spawned = false;
    if(act > 0.02){
      T.accDust += 110*act*dt; T.accIon += 160*act*dt;
      while(T.accDust >= 1){ T.accDust -= 1; spawnTailParticle(T, T.nextDust, false, p, vel, anti, act); T.nextDust = (T.nextDust + 1) % TAIL_N_DUST; spawned = true; }
      while(T.accIon >= 1){ T.accIon -= 1; spawnTailParticle(T, T.nextIon, true, p, vel, anti, act); T.nextIon = T.nextIon + 1 >= TAIL_N ? TAIL_N_DUST : T.nextIon + 1; spawned = true; }
    }
    const P = T.P, V = T.V;
    for(let k=0;k<TAIL_N;k++){
      if(T.life[k] <= 0) continue;
      const age = (T.age[k] += dt);
      if(age >= T.life[k]){ T.life[k] = 0; T.A[k] = 0; continue; }
      const j = k*3;
      if(k < TAIL_N_DUST && ssSunAlive){                 // dust: gravity, weakened by the push of sunlight
        const x = P[j], y = P[j+1], z = P[j+2], r2 = x*x + y*y + z*z, r = Math.sqrt(r2);
        const g = (1 - T.beta[k])*MU_T0/(Math.max(r2, 1)*Math.max(r, 1))*dt;
        V[j] -= x*g; V[j+1] -= y*g; V[j+2] -= z*g;
      }
      P[j] += V[j]*dt; P[j+1] += V[j+1]*dt; P[j+2] += V[j+2]*dt;
      const t = age/T.life[k], fade = t < 0.08 ? t/0.08 : Math.pow(1 - t, 1.6);
      T.A[k] = T.bright[k]*fade;
      T.S[k] = k < TAIL_N_DUST ? 0.22 + 0.9*t : 0.2 + 0.4*t;         // spreads as it ages
    }
    const at = T.geo.attributes;
    at.position.needsUpdate = true; at.aAlpha.needsUpdate = true; at.aSize.needsUpdate = true;
    if(spawned) at.aColor.needsUpdate = true;
  }

  function dotCloud(P, C, px){
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(new Float32Array(P), 3));
    geo.setAttribute('color', new THREE.BufferAttribute(new Float32Array(C), 3));
    const mat = new THREE.PointsMaterial({map:STARFIELD_POINT_TEXTURE, size:px, sizeAttenuation:false, vertexColors:true,
      transparent:true, depthWrite:false, blending:THREE.AdditiveBlending, fog:false});
    const pts = new THREE.Points(geo, mat);
    pts.frustumCulled = false;
    return pts;
  }
  // a ring of dots between rMin..rMax AU, split into radial bands that each turn at their own rate
  function beltBands(rng, o){
    const edges = []; for(let i=0;i<=o.bands;i++) edges.push(o.rMin + (o.rMax - o.rMin)*i/o.bands);
    const bins = edges.slice(1).map(()=>({P:[], C:[]}));
    let made = 0;
    while(made < o.count){
      const aAU = o.rMin + (o.rMax - o.rMin)*Math.pow(rng(), o.bias || 1);
      if(o.gaps && o.gaps.some(g => Math.abs(aAU - g) < 0.035)) continue;   // Kirkwood gaps
      const th = rng()*Math.PI*2, r = aAU*AU;
      const y = gauss(rng)*r*o.thick;
      const bi = Math.min(o.bands-1, Math.floor((aAU - o.rMin)/(o.rMax - o.rMin)*o.bands));
      bins[bi].P.push(Math.cos(th)*r, y, Math.sin(th)*r);
      const k = o.kLo + rng()*(o.kHi - o.kLo);
      bins[bi].C.push(o.col[0]*k, o.col[1]*k, o.col[2]*k);
      made++;
    }
    bins.forEach((b, i)=>{
      const aMid = (edges[i] + edges[i+1])/2;
      const pts = dotCloud(b.P, b.C, o.px);
      pts.rotation.y = rng()*Math.PI*2;
      uExtras.add(pts);
      uExtraBands.push({ points:pts, omega: Math.PI*2/(60*Math.pow(aMid, 1.5)) });
    });
  }
  // name, a (AU), e, i, ascending node, argument of perihelion (deg), radius (Earth radii). Real orbit
  // shapes and orientations; where along the orbit each one starts is approximate.
  const MINOR_BODIES = [
    ['Ceres',    2.767, 0.079, 10.59,  80.3,  73.6, 0.074],
    ['Vesta',    2.362, 0.089,  7.14, 103.8, 151.2, 0.041],
    ['Pallas',   2.772, 0.230, 34.84, 173.0, 310.1, 0.040],
    ['Hygiea',   3.139, 0.112,  3.83, 283.2, 312.3, 0.034],
    ['Haumea',  43.12,  0.195, 28.21, 122.2, 239.0, 0.128],
    ['Makemake',45.43,  0.162, 29.01,  79.6, 296.5, 0.112],
  ];
  // name, a (AU), e, i, node, perihelion argument (deg), starting mean anomaly (rad; negative = before perihelion)
  const COMETS = [
    ['Comet Encke',              2.22, 0.848,  11.8, 334.6, 186.5, -0.35],
    ["Halley's Comet",          17.8,  0.967, 162.3,  58.4, 111.3, -0.056],
    ['67P/Churyumov–Gerasimenko',3.46, 0.641,   7.0,  50.1,  12.8,  2.2],
    ['Tempel 1',                 3.14, 0.510,  10.5,  68.9, 179.2, -1.4],
    ['Tempel–Tuttle',           10.3,  0.906, 162.5, 235.3, 172.5,  2.9],
    ['Swift–Tuttle',            26.1,  0.963, 113.5, 139.4, 153.0, -2.6],
  ];
  function addExtraLabel(obj, text, color){
    const s = makeLabel(text, color); uExtras.add(s); uExtraLabels.push({ sprite:s, obj });
  }
  function buildSolarExtras(){
    uExtras = new THREE.Group(); uExtraBands = []; uMinor = []; uComets = []; uExtraLabels = []; uTime = 0;
    const rng = mulberry32(1801);
    // main belt 2.1-3.3 AU with the 3:1, 5:2 and 7:3 Kirkwood gaps; Kuiper belt 39-48 AU (plutinos at 39.4)
    beltBands(rng, { count:3200, rMin:2.1, rMax:3.3, bands:6, thick:0.06, gaps:[2.50, 2.82, 2.95], col:[0.82,0.74,0.64], kLo:0.25, kHi:0.75, px:1.7 });
    beltBands(rng, { count:900,  rMin:39.2, rMax:39.8, bands:1, thick:0.12, col:[0.62,0.72,0.9], kLo:0.2, kHi:0.55, px:1.6 });
    beltBands(rng, { count:2800, rMin:42, rMax:48, bands:3, thick:0.05, col:[0.62,0.72,0.9], kLo:0.2, kHi:0.55, px:1.6 });
    const mbl = makeLabel('Main asteroid belt', '#bfb3a6'); mbl.position.set(Math.cos(0.8)*2.7*AU, 0, Math.sin(0.8)*2.7*AU); uExtras.add(mbl);
    const kbl = makeLabel('Kuiper belt', '#a9bfe6'); kbl.position.set(Math.cos(2.3)*44*AU, 0, Math.sin(2.3)*44*AU); uExtras.add(kbl);
    // Jupiter trojans: swarms 60 degrees ahead of (L4) and behind (L5) Jupiter on its orbit
    uTrojans = new THREE.Group();
    const P = [], C = [];
    for(const lead of [1, -1]){
      for(let i=0;i<700;i++){
        const th = lead*Math.PI/3 + gauss(rng)*0.2, r = (5.2 + gauss(rng)*0.12)*AU;
        P.push(Math.cos(th)*r, gauss(rng)*r*0.08, Math.sin(th)*r);
        const k = 0.25 + rng()*0.45; C.push(0.8*k, 0.72*k, 0.62*k);
      }
    }
    uTrojans.add(dotCloud(P, C, 1.7));
    const tl = makeLabel('Jupiter trojans', '#bfb3a6'); tl.position.set(Math.cos(Math.PI/3)*5.2*AU, 0, Math.sin(Math.PI/3)*5.2*AU); uTrojans.add(tl);
    uExtras.add(uTrojans);
    // named asteroids and dwarf planets: same sprite/3D convention as the Earth-mode belt objects
    for(const [name, a, e, incDeg, node, peri, size] of MINOR_BODIES){
      let mesh;
      if(renderMode === '2d') mesh = makeSpritePlanet(ASTEROID_TEXTURE, ASTEROID_TEX_ASPECT, size);
      else mesh = new THREE.Mesh(new THREE.SphereGeometry(size, 10, 10), new THREE.MeshStandardMaterial({color:0xffffff, map:picSphereTex('asteroid'), roughness:0.9, fog:false}));
      uExtras.add(mesh);
      const glow = makeGlow(0xd8cbbd, 0.008); uExtras.add(glow);   // findable from afar
      const body = { name, size, mesh, glow, el:{ a, e, i:incDeg*D2R, node:node*D2R, peri:peri*D2R, P:60*Math.pow(a, 1.5) },
        M:rng()*Math.PI*2, spin:(rng() < 0.5 ? -1 : 1)*(2 + rng()*6), rot:0 };
      uMinor.push(body);
      addExtraLabel(mesh, name, '#d8cbbd');
    }
    // comets: the same 2D comet sprite as every other comet (a small sphere in 3D), a coma glow that
    // brightens toward the Sun, and particle tails (curving dust, near-straight blue ions)
    for(const [name, a, e, i, node, peri, M0] of COMETS){
      const NUC = 0.08;
      const coma = renderMode === '2d' ? makeSpritePlanet(COMET_TEXTURE, COMET_TEX_ASPECT, NUC)
        : new THREE.Mesh(new THREE.SphereGeometry(NUC, 8, 8), new THREE.MeshStandardMaterial({color:0xffffff, map:picSphereTex('comet'), roughness:0.7, fog:false}));
      uExtras.add(coma);
      const halo = makeBodyGlow(0xcfeaff, 1); uExtras.add(halo);
      const glowPx = makeGlow(0x9fdcff, 0.009); uExtras.add(glowPx);
      const tail = makeCometTail(); uExtras.add(tail.points);
      const c = { el:{a, e, i:i*Math.PI/180, node:node*Math.PI/180, peri:peri*Math.PI/180, P:60*Math.pow(a, 1.5)}, M:M0,
        coma, halo, glowPx, tail, spin:(rng() < 0.5 ? -1 : 1)*(0.4 + rng()*0.8), prev:new THREE.Vector3(), name };
      uComets.push(c);
      addExtraLabel(coma, name, '#bfe3ff');
    }
    scene.add(uExtras);
    updateSolarExtras(0);
  }
  // heliocentric ecliptic position of a comet at mean anomaly M (Kepler's equation, Newton's method),
  // mapped into this tier's frame: game = (ecliptic x, -ecliptic z, ecliptic y) * AU
  function cometPosition(el, M, out){
    // wrap M into [0, 2pi): starting Newton at E = pi only converges reliably for M in that range
    // (a negative M sent high-eccentricity comets like Swift-Tuttle to the wrong place)
    M = ((M % (Math.PI*2)) + Math.PI*2) % (Math.PI*2);
    let E = el.e < 0.8 ? M : Math.PI;
    for(let k=0;k<12;k++) E -= (E - el.e*Math.sin(E) - M)/(1 - el.e*Math.cos(E));
    const nu = 2*Math.atan2(Math.sqrt(1+el.e)*Math.sin(E/2), Math.sqrt(1-el.e)*Math.cos(E/2));
    const r = el.a*(1 - el.e*Math.cos(E));
    const u = el.peri + nu, cO = Math.cos(el.node), sO = Math.sin(el.node), ci = Math.cos(el.i);
    const x = r*(cO*Math.cos(u) - sO*Math.sin(u)*ci);
    const y = r*(sO*Math.cos(u) + cO*Math.sin(u)*ci);
    const z = r*(Math.sin(u)*Math.sin(el.i));
    return out.set(x*AU, -z*AU, y*AU);
  }
  // the Sun is gone: every belt, the trojans, the named bodies and the comets keep their momentum
  // and fall free (the belts become loose particles; the black hole sweeps them one by one from here on)
  function releaseSolarExtras(){
    uExtrasFree = true;
    const loose = [];
    for(const b of uExtraBands) loose.push([b.points, b.omega, b.points.rotation.y]);
    if(uTrojans){
      const jup = PLANET_ELEMENTS.jupiter;
      for(const c of uTrojans.children){
        if(c.isPoints) loose.push([c, Math.PI*2/(60*Math.pow(jup[0], 1.5)), uTrojans.rotation.y]);
        else c.visible = false;                                                // the swarms scatter: drop their label
      }
      uTrojans.rotation.y = 0;
    }
    for(const [pts, omega, phi] of loose){
      const A = pts.geometry.attributes.position, n = A.count, V = new Float32Array(n*3);
      const c = Math.cos(phi), sn = Math.sin(phi);
      for(let k=0;k<n;k++){
        const x = A.array[k*3], z = A.array[k*3+2];
        const X = x*c + z*sn, Z = -x*sn + z*c;                    // where it is now (undo the ring's turn)
        A.array[k*3] = X; A.array[k*3+2] = Z;
        V[k*3] = -omega*Z; V[k*3+2] = omega*X;                     // prograde, at the ring's rate
      }
      pts.rotation.y = 0; A.needsUpdate = true;
      uFreeParticles.push({ points:pts, V });
      const cl = uClouds.find(u => u.points === pts); if(cl) cl.dynamic = true;
    }
    uExtraBands = [];
    for(const m of uMinor){ m.vel = m.pp && m.pdt > 0 ? m.mesh.position.clone().sub(m.pp).divideScalar(m.pdt) : new THREE.Vector3(); m.free = true; }
    for(const cm of uComets){ cm.vel = cm.prev.lengthSq() > 0 && cm.pdt > 0 ? cm.coma.position.clone().sub(cm.prev).divideScalar(cm.pdt) : new THREE.Vector3(); cm.free = true; }
  }
  // loose particles (released belts and discs): same gravity as everything else knocked loose
  let uFreeParticles = [];
  // what pulls on loose things this frame, as plain numbers [x, y, z, GM, core radius] (dust loops stay cheap)
  function gravitySources(inSystem){
    const S = [];
    if(!inSystem && ssSunAlive) S.push([0, 0, 0, MU_T0*gravityK, SUN_SIZE]);
    if(gameMode === 'maw'){
      const mu = inSystem ? 4*Math.PI*Math.PI*Math.pow(uSysScale.A, 3)/(uSysScale.Y*uSysScale.Y) : MU_T0;
      S.push([hole.pos.x, hole.pos.y, hole.pos.z, mu*mawGravMass(), hole.radius]);
    }
    return S;
  }
  function updateFreeParticles(dt, S){
    if(!uFreeParticles.length || dt <= 0) return;
    const n = dt > 0.025 ? 2 : 1, h = dt/n;
    const maw = gameMode === 'maw', R = hole.radius*1.5, R2 = R*R, hx = hole.pos.x, hy = hole.pos.y, hz = hole.pos.z;
    const perPoint = maw ? TIER_BUDGET[uTier]*uFood.pointShare/Math.max(1, uFood.points) : 0;
    for(const f of uFreeParticles){
      const A = f.points.geometry.attributes.position, P = A.array, V = f.V;
      const cl = maw ? uClouds.find(u => u.points === f.points) : null, eaten = cl ? cl.eaten : null;
      const Ca = cl ? f.points.geometry.attributes.color : null;
      let got = 0;
      for(let k=0, m=A.count*3; k<m; k+=3){
        if(eaten && eaten[k/3]) continue;                                      // swallowed: nothing left to move
        let x = P[k], y = P[k+1], z = P[k+2], vx = V[k], vy = V[k+1], vz = V[k+2];
        for(let s2=0;s2<n;s2++){
          for(let j=0;j<S.length;j++){
            const g = S[j], dx = g[0]-x, dy = g[1]-y, dz = g[2]-z, r2 = dx*dx + dy*dy + dz*dz, r = Math.sqrt(r2);
            const a = (r > g[4] ? g[3]/(r2*r) : g[3]/(g[4]*g[4]*g[4]))*h;
            vx += dx*a; vy += dy*a; vz += dz*a;
          }
          x += vx*h; y += vy*h; z += vz*h;
        }
        P[k] = x; P[k+1] = y; P[k+2] = z; V[k] = vx; V[k+1] = vy; V[k+2] = vz;
        if(eaten){                                                             // the black hole's sweep, same rules as sweepClouds
          const dx = x - hx, dy = y - hy, dz = z - hz;
          if(dx*dx + dy*dy + dz*dz <= R2){
            eaten[k/3] = 1; got++;
            uPending.col.setRGB(Ca.array[k], Ca.array[k+1], Ca.array[k+2]); uPending.pos.set(x, y, z);
            Ca.array[k] = Ca.array[k+1] = Ca.array[k+2] = 0;
          }
        }
      }
      A.needsUpdate = true;
      if(got){ Ca.needsUpdate = true; uPending.dr += got*perPoint; uPending.n += got; }
    }
  }
  let uExtrasFree = false;
  function updateSolarExtras(dt){
    if(!uExtras) return;
    uTime += dt;
    if(!ssSunAlive && !uExtrasFree) releaseSolarExtras();
    updateFreeParticles(dt, gravitySources(false));
    for(const b of uExtraBands) b.points.rotation.y -= b.omega*dt;           // same sense as the planets
    const jup = solarSystemBodies && solarSystemBodies.find(b => b.name === 'jupiter');
    // the trojans stay 60 degrees ahead of / behind wherever Jupiter really is
    if(jup && uTrojans && !uExtrasFree) uTrojans.rotation.y = -Math.atan2(jup.mesh.position.z, jup.mesh.position.x);
    for(const m of uMinor){
      if(!m.pp) m.pp = new THREE.Vector3();
      else if(!m.free && m.pdt > 0 && mawBeats(m.mesh.position, (ssSunAlive ? MU_T0/Math.max(m.mesh.position.lengthSq(), 1) : 0)*MAW_PERTURB, MU_T0)){
        m.vel = m.mesh.position.clone().sub(m.pp).divideScalar(m.pdt); m.free = true;          // pulled off its orbit
      }
      m.pp.copy(m.mesh.position); m.pdt = dt;
      if(m.free){ if(dt > 0) freeFly(m.mesh.position, m.vel, dt, ssAccel); intoSun(m.mesh, m.size || 0); }
      else { m.M += dt/m.el.P*Math.PI*2; cometPosition(m.el, m.M, m.mesh.position); }
      m.glow.position.copy(m.mesh.position);
      m.rot += dt/Math.abs(m.spin)*Math.PI*2*Math.sign(m.spin);
      if(m.mesh.userData.spriteMat) m.mesh.userData.spriteMat.rotation = m.rot; else m.mesh.rotation.y = m.rot;
    }
    const tailScale = (renderer && renderer.domElement && renderer.domElement.height || window.innerHeight || 800)/(2*Math.tan((camera.fov || 60)*Math.PI/360));
    for(const c of uComets){
      if(!c.free && c.pdt > 0 && c.prev.lengthSq() > 0 && mawBeats(c.coma.position, (ssSunAlive ? MU_T0/Math.max(c.coma.position.lengthSq(), 1) : 0)*MAW_PERTURB, MU_T0)){
        c.vel = c.coma.position.clone().sub(c.prev).divideScalar(c.pdt); c.free = true;       // pulled off its orbit
      }
      c.prev.copy(c.coma.position); c.pdt = dt;
      let p;
      if(c.free){ if(dt > 0) freeFly(c.coma.position, c.vel, dt, ssAccel); p = c.coma.position; intoSun(c.coma, 0); }
      else { c.M += dt/c.el.P*Math.PI*2; p = cometPosition(c.el, c.M, c.coma.position); }
      c.glowPx.position.copy(p); c.halo.position.copy(p);
      if(c.coma.userData.spriteMat) c.coma.userData.spriteMat.rotation += c.spin*dt; else c.coma.rotation.y += c.spin*dt;   // a slow tumble
      const rAU = p.length()/AU;
      // activity: tails switch on inside a few AU and grow sharply toward the Sun (no Sun, no tails)
      const act = ssSunAlive ? Math.pow(clamp(1.6/rAU, 0, 1), 2.5) : 0;   // tails only within ~6 AU
      c.halo.scale.setScalar(0.15 + 2.0*act);
      c.halo.material.opacity = 0.12 + 0.6*act;
      const vel = dt > 0 && c.prev.lengthSq() > 0 ? cTmpB.copy(p).sub(c.prev).divideScalar(dt) : cTmpB.set(0,0,0);
      c.tail.points.material.uniforms.uScale.value = tailScale;
      updateCometTail(c.tail, p, vel, act, dt);
    }
    for(const l of uExtraLabels) l.sprite.position.copy(l.obj.position);
  }
  function removeSolarExtras(){
    if(uExtras){ scene.remove(uExtras); disposeUniverseObj(uExtras); }
    uExtras = null; uExtraBands = []; uTrojans = null; uMinor = []; uComets = []; uExtraLabels = [];
    uFreeParticles = []; uExtrasFree = false;
  }

  // ======================= every mode on the tier map (Earth mode excepted) =======================
  // the black hole, Ship and Passive start where Universe starts and move through the same tiers. the black hole eats what it
  // touches (bigger things just take longer) with no size cap. Growth is tier-relative: each tier has an
  // arrival size S and a "graduated" size G, and eating everything in a tier is worth ~1.2 x (G - S).
  // Jumping tiers rescales the black hole by the same stitch the tiers use for position, so its size relative to
  // the world carries across the jump (T2<->T3 and galaxy interiors are geometric; home seams designed).
  const TIER_AVATAR_MODES = new Set(['maw','ship','passive']);
  function tierAvatar(){ return TIER_AVATAR_MODES.has(gameMode) && !randomActive; }
  function inTierWorld(){ return gameMode === 'universe' || tierAvatar(); }
  const SYSTEM_TIER = 7;
