    if(PLANET_GLOBES[v.name]) spec.tex = planetTexture3D(PLANET_GLOBES[v.name]);     // (Earth too: the map you see from afar)
    const isMoonBody = v.name === 'moon' || (v.extra && v.extra.rec && v.extra.rec.isMoon);
    if(isMoonBody && MOON_MODEL === 'globe') spec.tex = moonEquirect(v.name === 'moon' ? null : (v.extra && v.extra.color));
