        const o = m.o; o.M += dt/o.P*Math.PI*2;
        let r = o.d, nu = o.M;
        if(o.e){ const E = keplerE(o.e, o.M); r = o.d*(1 - o.e*Math.cos(E)); nu = 2*Math.atan2(Math.sqrt(1+o.e)*Math.sin(E/2), Math.sqrt(1-o.e)*Math.cos(E/2)); }
