      if(T.wallR && uPreMoveDC > T.wallR){ hole.pos.setLength(T.wallR); uTmp.copy(hole.pos).normalize(); const out = hole.vel.dot(uTmp); if(out > 0) hole.vel.addScaledVector(uTmp, -out); }
      return;
