        let turn = 0;
        if(hv){ apC.copy(P).sub(hole.pos); const L = apC.length(); if(L > 1e-9) turn = Math.acos(clamp(hv.dot(apC.divideScalar(L)), -1, 1))*turnK; }
        let score = Math.sqrt(val)/((c.d + turn)/v + 0.4);
        if(c.b === apCurB) score *= 1.35;                    // (sticks to its choice unless another is clearly better)
        if(score > bestScore){ bestScore = score; best = { body:c.b, small:c.small }; bestCost = c.d; }
