      if(!ship.fall){ ship.fall = true; ship.vel = dt > 0 ? ship.pos.clone().sub(ship.prev).divideScalar(Math.max(dt, 1e-3)) : new THREE.Vector3(); }
      ship.prev.copy(ship.pos);
