    const f = aiU.dot(aiR), sx = aiU.dot(right), a = Math.abs(Math.atan2(sx, -f)*180/Math.PI);   // 0: coming at you, 180: going away
    let key = null, flip = false, aspect = SHIP_TEX_ASPECT;
    if(ship.kind === 'classic'){                                                         // one view: turned to its heading
      const up = aiR.set(0, 1, 0).applyQuaternion(camera.quaternion);
      sp.material.rotation = Math.atan2(aiU.dot(up), sx) - Math.PI/2;
    } else if(ship.kind === 'shuttle'){
      key = a < 45 ? 'shuttle_front' : a > 135 ? 'shuttle_back' : 'shuttle_side';
      flip = key === 'shuttle_side' && sx > 0;                                          // drawn nose-left
    } else {
      key = a < 22.5 ? 'miner_front' : a < 67.5 ? 'miner_fdiag' : a < 112.5 ? 'miner_side' : a < 157.5 ? 'miner_bdiag' : 'miner_back';
      flip = key === 'miner_fdiag' ? sx > 0 : (key === 'miner_side' || key === 'miner_bdiag') ? sx < 0 : false;   // drawn heading left / right
    }
    if(key){ const T = AI_TEX[key]; if(sp.material.map !== T.tex){ sp.material.map = T.tex; sp.material.needsUpdate = true; } sp.material.rotation = 0; aspect = T.aspect; }
    const h = Math.max(K.world, pxToWorld(AI_MIN_PX, dist));                             // tiny: a speck from afar
