  // satellites and the Moon rocket, drawn small on canvases
  const SAT_TEX = (function(){
    const c = document.createElement('canvas'); c.width = 32; c.height = 16; const g = c.getContext('2d');
    g.fillStyle = '#3d6bd6'; g.fillRect(1, 5, 10, 6); g.fillRect(21, 5, 10, 6);
    g.fillStyle = '#9ab8ff'; for(let x=2;x<11;x+=3){ g.fillRect(x, 6, 1, 4); g.fillRect(x + 20, 6, 1, 4); }
    g.fillStyle = '#d9b25a'; g.fillRect(12, 4, 8, 8); g.fillStyle = '#f2e3b3'; g.fillRect(13, 5, 3, 3);
    return new THREE.CanvasTexture(c);
  })();
  const ROCKET_TEX = (function(){
    const c = document.createElement('canvas'); c.width = 12; c.height = 32; const g = c.getContext('2d');
    g.fillStyle = '#f2f2f2'; g.fillRect(4, 6, 4, 20); g.fillStyle = '#d23c3c'; g.fillRect(5, 2, 2, 4); g.fillRect(4, 5, 4, 2);
    g.fillStyle = '#9a9aa8'; g.fillRect(1, 20, 3, 7); g.fillRect(8, 20, 3, 7); g.fillStyle = '#5a5a66'; g.fillRect(4, 26, 4, 2);
    return new THREE.CanvasTexture(c);
  })();
  function addSatellite(){
    if(!SATELLITES_ENABLED) return;
    const s = new THREE.Sprite(new THREE.SpriteMaterial({ map:SAT_TEX, transparent:true, depthWrite:false, fog:false })); scene.add(s);
    const n = new THREE.Vector3(Math.random() - 0.5, (Math.random() - 0.5)*0.6, Math.random() - 0.5).normalize();
    const u = new THREE.Vector3(1, 0, 0); if(Math.abs(n.x) > 0.9) u.set(0, 1, 0);
    u.addScaledVector(n, -u.dot(n)).normalize(); const v = new THREE.Vector3().crossVectors(n, u);
    const high = Math.random() < 0.25;                                                   // most low, some out at geostationary
    const er = earthBodyRef ? bodyVisR(earthBodyRef) : 1;                              // over the drawn Earth
    uSats.push({ sprite:s, u, v, r: er*(high ? 2.1 + Math.random()*0.2 : 1.15 + Math.random()*0.5), P: high ? 9 : 2.6 + Math.random()*2.5, a:Math.random()*6.283 });
  }
  function updateSatellites(dt){
    const e = earthBodyRef, alive = e && solarSystemBodies.includes(e);
    for(const s of uSats.slice()){
      if(s.vel){                                                              // pulled off its orbit: falling toward the black hole
        if(dt > 0) freeFly(s.sprite.position, s.vel, dt, ssAccel);
        if(s.sprite.position.distanceTo(hole.pos) < hole.radius){            // swallowed
          scene.remove(s.sprite); disposeUniverseObj(s.sprite); uSats.splice(uSats.indexOf(s), 1);
          if(uAge) uAge.sats = Math.max(0, uAge.sats - 1);
          continue;
        }
        const h = Math.max(0.0015, pxToWorld(AI_MIN_PX*0.7, camera.position.distanceTo(s.sprite.position)));
        s.sprite.scale.set(h*2, h, 1); s.sprite.visible = true; continue;
      }
      s.sprite.visible = !!alive; if(!alive) continue;
      if(mawBeats(s.sprite.position, 4*Math.PI*Math.PI*s.r/(s.P*s.P), MU_T0)){
        const vt = 6.283*s.r/s.P;                                              // its orbital velocity, plus Earth's
        s.vel = new THREE.Vector3().addScaledVector(s.u, -Math.sin(s.a)*vt).addScaledVector(s.v, Math.cos(s.a)*vt).add(e.vlast || new THREE.Vector3());
        continue;
      }
      s.a += dt/s.P*6.283;
      const c = Math.cos(s.a)*s.r, sn = Math.sin(s.a)*s.r, p = e.mesh.position;
      s.sprite.position.set(p.x + s.u.x*c + s.v.x*sn, p.y + s.u.y*c + s.v.y*sn, p.z + s.u.z*c + s.v.z*sn);
      const h = Math.max(0.0015, pxToWorld(AI_MIN_PX*0.7, camera.position.distanceTo(s.sprite.position)));
      s.sprite.scale.set(h*2, h, 1);
    }
  }
  // Earth's first rocket to the Moon: burn, transfer arc, a few loops of the Moon, then down to its surface
  // ---- rockets to the Moon (Luna 2 in 1959, Apollo 11 in 1969: see Earth's history below) ----
  // The flight is drawn in Earth's frame and then the Moon's (both move fast on the game clock: Earth ~6 units/s
  // round the Sun, the Moon round Earth every few seconds), so it never wanders off through space. It climbs out
  // on a curve aimed at where the Moon will be when it arrives, makes one orbit, then brakes down to the surface
