  // the race whose home world's past the pop-ups follow: the one you've picked (Earth mode = Earth, Home World = its own)
  let homeView = null;
  function histRace(){
    if(homeView) return homeView.race;
    if(gameMode === 'earth') return 'human';
    try { return mySide(); } catch(e){ return 'human'; }
  }
  // a race's home planet, when you're in its system
  function homeBodyIn(race){
    const H = HOME_OF[race];
    if(!H || !H.system || uTier !== SYSTEM_TIER || !uSystem || uSystem.name !== H.system || !uTargets) return null;
    const t = uTargets.find(b => b.type === 'planet' && b.mesh && b.mesh.parent && (H.planet instanceof RegExp ? H.planet.test(b.name) : b.name === H.planet));
    if(t && t.alive === undefined) t.alive = true;            // (targets carry no alive flag of their own)
    return t || null;
  }
  // what happens on the other home worlds, drawn when you're there: impacts, bursts, bombardments, launches
  const sysFx = [];
  function sysFxClear(){ for(const f of sysFx){ for(const g of [f.g, f.flash]) if(g){ scene.remove(g); disposeUniverseObj(g); } } sysFx.length = 0; }
  function sysImpact(b, big, comet, air){
    const R = Math.max(bodyVisR(b), 1e-6), dir = visibleSpot(b, 0.7);
    const side = randUnit(new THREE.Vector3()).multiplyScalar(R*(1 + Math.random()));
    const start = dir.clone().multiplyScalar(R*(3.2 + 1.6*Math.random())).add(side);
    const g = makeGlow(comet ? 0xbfe6ff : 0xffd8a8, 0.005 + 0.005*big); g.material.opacity = 0; scene.add(g);
    sysFx.push({ b, sys:uSystem, dir, start, g, flash:null, t:0, dur:1.3 + 0.4*Math.random(), big, air, kind:'impact' });
  }
  function sysLaunch(b){
    const R = Math.max(bodyVisR(b), 1e-6), dir = visibleSpot(b, 0.5);
    const g = makeGlow(0xcfe8ff, 0.005); g.material.opacity = 0; scene.add(g);
    sysFx.push({ b, sys:uSystem, dir, start:dir.clone().multiplyScalar(R*1.02), g, flash:null, t:0, dur:3.2, big:0, kind:'launch' });
  }
  const _sfx = new THREE.Vector3();
  function sysFxStep(dt){
    const A = uAge;
    if(A && A.flurry){                                     // (a bombardment: a run of strikes over a dozen seconds)
      const F = A.flurry;
      if(A.t >= F.until) A.flurry = null;
      else if(A.t >= F.next){ F.next = A.t + 0.45 + Math.random()*0.8; const b = homeBodyIn(F.race); if(b) sysImpact(b, 0.15 + Math.random()*0.35, F.comet && Math.random() < 0.6, false); }
    }
    for(let i=sysFx.length-1;i>=0;i--){
      const f = sysFx[i], gone = !f.b.alive || !f.b.mesh || uTier !== SYSTEM_TIER || uSystem !== f.sys;
      f.t += dt;
      const R = Math.max(bodyVisR(f.b), 1e-6), done = () => { for(const g of [f.g, f.flash]) if(g){ scene.remove(g); disposeUniverseObj(g); } sysFx.splice(i, 1); };
      if(gone){ done(); continue; }
      const P = f.b.mesh.position;
      if(f.kind === 'launch'){
        const s = Math.min(1, f.t/f.dur);
        f.g.position.copy(P).add(_sfx.copy(f.dir).multiplyScalar(R*(1.02 + 5*s*s)));
        f.g.material.opacity = Math.min(1, f.t*3)*(1 - s);
        if(s >= 1) done();
        continue;
      }
      const s = Math.min(1, f.t/f.dur), k = Math.pow(s, 1.6);
      f.g.position.copy(P).add(_sfx.copy(f.start).lerp(histV.copy(f.dir).multiplyScalar(R*(f.air ? 1.12 : 1.0)), k));
      f.g.material.opacity = Math.min(1, f.t*2);
      if(s >= 1 && !f.flash){
        f.flash = makeGlow(f.air ? 0xfff2cc : 0xffe0b0, 0.012 + 0.03*f.big); scene.add(f.flash);
        f.flash.position.copy(f.g.position); f.g.material.opacity = 0; f.ft = 0;
      }
      if(f.flash){
        f.ft += dt; f.flash.position.copy(P).add(_sfx.copy(f.dir).multiplyScalar(R*(f.air ? 1.12 : 1.0)));
        f.flash.material.opacity = Math.max(0, 1 - f.ft/1.4);
        if(f.ft >= 1.4) done();
      }
    }
  }
  function fireRaceHist(race, ev){
    if(ev.caption && race === histRace()) histSay(ev.caption);
    const b = homeBodyIn(race);
    if(ev.kind === 'flurry'){ uAge.flurry = { race, until:uAge.t + 12, next:uAge.t, comet:!!ev.comet }; return; }
    if(!b) return;
    if(ev.kind === 'impact' || ev.kind === 'airburst') sysImpact(b, ev.big || 0.5, !!ev.comet, ev.kind === 'airburst');
    else if(ev.kind === 'launch') sysLaunch(b);
  }
  // Home World mode (Earth mode, for a race whose home isn't Earth): you ride along with your home planet
  const _homeD = new THREE.Vector3();
  function homeRide(){
    if(!homeView || gameMode !== 'universe') return;
    const b = homeBodyIn(homeView.race);
    homeView.body = b;                                     // (the camera locks onto it: homeCam)
  }
  // Earth-mode controls for Earth, and for a home world
  function earthLike(){ return gameMode === 'earth' || !!(homeView && gameMode === 'universe'); }
  // the camera on the home planet: centred on it, at Earth mode's distance for its size, turning with your drag
  const _hcD = new THREE.Vector3();
  function homeCam(){
    const b = homeView && homeView.body; if(!b || !b.mesh) return false;
    const p = b.mesh.position, R = Math.max(bodyVisR(b), 1e-6);
    hole.pos.copy(p); hole.vel.set(0, 0, 0);
    const dist = R*(BASE_CAM_DIST + CAM_ZOOM_PER_RADIUS)*chaseZoom;
    _hcD.copy(camOffset).normalize().multiplyScalar(dist).add(p);
    if(!homeView.cam){ homeView.cam = _hcD.clone(); } else homeView.cam.lerp(_hcD, 0.12);   // (eased on its own: Universe mode re-seats the camera every frame)
    camera.position.copy(homeView.cam); camera.lookAt(p); parkSky();
    return true;
  }
  // ice (0 none .. 1 pole to equator), eruptions, warmth: each episode at least a few seconds on screen
  const CLIMATE = [
    { y0:-2.4e9, y1:-2.1e9, ice:0.8, min:6, hemi:0 }, { y0:-7.2e8, y1:-6.35e8, ice:1.0, min:7, hemi:0 }, { y0:-3.6e8, y1:-2.6e8, ice:0.5, min:5, hemi:-1 },
    { y0:-2.52e8, y1:-2.5e8, volc:1, min:3.5 }, { y0:-5.6e7, y1:-5.5e7, warm:1, min:3.5 }, { y0:-2.6e6, y1:-1.17e4, ice:0.38, cycles:true, min:4, hemi:1 } ];
  for(const c of CLIMATE){ c.t0 = histT(c.y0); c.t1 = Math.max(histT(c.y1), c.t0 + c.min); }
  function climateAt(t){
    const o = { ice:0, volc:0, warm:0, iceBias:0 };
    for(const c of CLIMATE){
      if(c.fut && gameMode !== 'earth') continue;            // (v266: the future's climate: Earth mode only)
      const out = c.ice ? 3 : 1.5;                         // (ice melts back over a few seconds)
      if(t < c.t0 || t > c.t1 + out) continue;
      const rise = c.ice && !c.cycles ? Math.max(1, (c.t1 - c.t0)*0.45) : 1;   // (ice spreads over much of its episode)
      const k = Math.min(clamp((t - c.t0)/rise, 0, 1), clamp(1 - (t - c.t1)/out, 0, 1)), e = k*k*(3 - 2*k);
      if(c.ice){ if(c.ice*e > o.ice) o.iceBias = c.hemi || 0;
        let a = c.ice;
        if(c.cycles){                                      // (sheets growing and shrinking, the biggest at the end, 20,000 years ago)
          const lgm = histT(-2e4), u = clamp((t - c.t0)/Math.max(lgm - c.t0, 1e-3), 0, 1);
          a = 0.18 + 0.2*(0.5 + 0.5*Math.sin(u*Math.PI*9 - Math.PI/2))*(0.4 + 0.6*u) + 0.2*Math.max(0, 1 - Math.abs(t - lgm)/1.2);
        }
        o.ice = Math.max(o.ice, a*e);
      }
      if(c.volc) o.volc = Math.max(o.volc, e);
      if(c.warm) o.warm = Math.max(o.warm, e);
    }
    return o;
  }
  // ======================= v266-270: EARTH'S FUTURE -- a two-hour film after the opening =======================
  // After today's opening (the birth of Earth to 2100, about 7 minutes) the story runs on for about two hours more, in
  // chapters, on the same clock. The Solar System stays real: the comets and asteroids that will really pass Earth, on
  // their real dates (Apophis, Halley, Bennu, Swift-Tuttle, 1950 DA), the ice ages and supervolcanoes to come, the stars
  // that drift close, Betelgeuse, the oceans boiling off as the Sun brightens, Andromeda, and the Sun's real end: red
  // giant, Mercury, Venus and Earth swallowed, the helium flash, a planetary nebula, a white dwarf. On top of that rides
