  // ---- the Sun: its size (x its drawn size) and colour through the ages ----
  const T_ = y => histT(y);
  function sunScaleAt(t){
    const k = (a, b) => clamp((t - a)/(b - a), 0, 1), e = x => x*x*(3 - 2*x);
    if(t < T_(4.5e9)) return 1 + 0.06*k(T_(1e8), T_(4.5e9));
    if(t < T_(7e9)) return 1.06 + 0.3*e(k(T_(4.5e9), T_(7e9)));
    if(t < T_(7.5e9)) return 1.36 + 0.09*e(k(T_(7e9), T_(7.5e9)));
    if(t < T_(7.59e9)) return 1.45 + 2.6*Math.pow(k(T_(7.5e9), T_(7.59e9)), 1.3);         // (to just past Earth's orbit)
    if(t < T_(7.62e9)) return 4.05 - 3.2*e(k(T_(7.59e9), T_(7.6e9)));                       // (the helium flash: it shrinks)
    if(t < T_(7.69e9)) return 0.85;
    if(t < T_(7.715e9)){ const g = 0.85 + 3.4*e(k(T_(7.69e9), T_(7.71e9))); return g*(1 + 0.06*Math.sin((t - T_(7.69e9))*0.9)); }
    if(t < T_(7.725e9)) return Math.max(0.065, 4.25*(1 - e(k(T_(7.715e9), T_(7.725e9)))));     // (its envelope blown away)
    return 0.065;                                                                             // (a white dwarf: about Earth's size)
  }
  function sunColourAt(t, out){
    const k = (a, b) => clamp((t - a)/(b - a), 0, 1);
    if(t < T_(4.5e9)) return out.setRGB(1, 1, 1);
    if(t < T_(7e9)){ const u = k(T_(4.5e9), T_(7e9)); return out.setRGB(1, 1 - 0.18*u, 1 - 0.38*u); }
    if(t < T_(7.59e9)){ const u = k(T_(7e9), T_(7.59e9)); return out.setRGB(1, 0.82 - 0.36*u, 0.62 - 0.36*u); }
    if(t < T_(7.69e9)){ const u = k(T_(7.59e9), T_(7.6e9)); return out.setRGB(1, 0.46 + 0.36*u, 0.26 + 0.36*u); }
    if(t < T_(7.715e9)){ const u = k(T_(7.69e9), T_(7.71e9)); return out.setRGB(1, 0.82 - 0.4*u, 0.62 - 0.4*u); }
    const u = k(T_(7.715e9), T_(7.725e9)); return out.setRGB(1 - 0.3*u, 0.42 + 0.5*u, 0.22 + 0.78*u);
  }
