      const obj = new THREE.Points(geo, new THREE.PointsMaterial({ map:STARFIELD_POINT_TEXTURE, vertexColors:true, size:2.2, sizeAttenuation:true, transparent:true, opacity:0.8, depthWrite:false, blending:THREE.AdditiveBlending }));
