      for(const s of uSats) if(s.sprite) s.sprite.visible = false;
      for(const a of uAI) if(a.sprite) a.sprite.visible = false;
      for(const h of uHist.ships){ if(h.obj) h.obj.visible = false; if(h.sprite) h.sprite.visible = false; }
