  // the colour sliders: locked until Earth mode is
  function sliderLocks(){
    const open = modeOpen('maw');
    for(const id of ['ps-bright', 'ps-sat', 'ps-contrast', 'mc-bri', 'mc-sat', 'mc-con', 'hs-bri', 'hs-sat', 'hs-con']){
      const el = document.getElementById(id); if(!el) continue;
      el.disabled = !open; const row = el.closest('.ps-row'); if(row) row.classList.toggle('slider-locked', !open);
    }
    for(const id of ['part-sliders', 'mc-sliders', 'hole-sliders']){
      const box = document.getElementById(id); if(!box) continue;
      let n = box.querySelector(':scope > .slider-lock-note');
      if(!open && !n){ n = document.createElement('div'); n.className = 'slider-lock-note'; n.textContent = 'sliders · locked · unlock with blackhole mode'; box.appendChild(n); }
      if(open && n) n.remove();
      // (once open: the buttons in the note's place -- a ship's paint DEFAULT · SHIP · FLEET; the menu's and the black hole's DEFAULT)
      const ACTS = { 'part-sliders':['ps', [['DEFAULT', paintDefault], ['SHIP', paintShipAll], ['FLEET', paintFleetAll]]],
        'mc-sliders':['mc', [['DEFAULT', menuDefault]]], 'hole-sliders':['hs', [['DEFAULT', holeDefault]]] }[id];
      if(ACTS){
        let a = box.querySelector(':scope > .ps-acts');
        if(open && !a){
          // (an invisible copy of the note holds the row at the note's height, so the box stays the size it was)
          a = document.createElement('div'); a.className = 'ps-acts';
          a.innerHTML = '<div class="slider-lock-note">sliders · locked · unlock with blackhole mode</div><div class="ps-btns"></div>';
          const row = a.lastChild;
          for(const [t, f] of ACTS[1]){
            const b = document.createElement('button'); b.textContent = t; b.id = ACTS[0] + '-' + t.toLowerCase();
            bindActivate(b, () => { SFX.fx('click'); f(); }); row.appendChild(b);
          }
          box.appendChild(a);
        }
        if(!open && a) a.remove();
      }
    }
  }
