  let buildTaps = 0, buildTapT = 0;
  window.addEventListener('pointerdown', e => {
    if(running) return;
    const el = document.getElementById('build-tag'); if(!el) return;
    const b = el.getBoundingClientRect();
    if(e.clientX < b.left - 14 || e.clientX > b.right + 14 || e.clientY < b.top - 14 || e.clientY > b.bottom + 14){ buildTaps = 0; return; }
    const now = performance.now(); if(now - buildTapT > 2500) buildTaps = 0; buildTapT = now;
    if(++buildTaps >= 4){ buildTaps = 0; codeFreeze(); }
  }, true);
  // (v254: the screen freezes for 5 s; top right, top left, bottom left, bottom right in that time unlocks CODES)
  function codeFreeze(){
    if(document.getElementById('code-freeze')) return;
    const f = document.createElement('div'); f.id = 'code-freeze'; document.body.appendChild(f);
    const ORDER = ['tr', 'tl', 'bl', 'br']; let k = 0;
    // (v255: everything stands still -- animation frames are held back and CSS animations paused until it ends)
    const raf0 = window.requestAnimationFrame, held = [];
    window.requestAnimationFrame = cb => { held.push(cb); return 0; };
    document.body.classList.add('code-frozen');
    let done = false;
    const end = () => { if(done) return; done = true; clearTimeout(f._t); f.remove(); document.body.classList.remove('code-frozen');
      window.requestAnimationFrame = raf0; lastT = performance.now(); for(const cb of held.splice(0)) raf0(cb); };
    f._t = setTimeout(end, 5000);
    const corner = (x, y) => { const w = innerWidth, h = innerHeight, cx = x < w*0.5 ? 'l' : 'r', cy = y < h*0.5 ? 't' : 'b'; return cy + cx; };   // (v256: quarters of the screen)
    const eat = e => { e.preventDefault(); e.stopPropagation(); };
    f.addEventListener('pointerdown', e => {
      eat(e); const c = corner(e.clientX, e.clientY);
      if(c === ORDER[k]) k++; else k = c === ORDER[0] ? 1 : 0;
      if(k === ORDER.length){ end(); codesOn = true; try { localStorage.setItem(CODES_KEY, '1'); } catch(e2){} progApply(); SFX.fx('click'); banner('UNLOCKED', 'CODES');
        // (v256: the Codes menu, straight up)
        try { if(!running){ showPage(worldOptionsScreen); const ci = document.getElementById('code-in'); ci.value = ''; document.getElementById('code-msg').textContent = ''; setTimeout(()=>ci.focus(), 350); } } catch(e3){} }
    }, true);
    for(const ev of ['pointerup', 'click', 'touchstart', 'touchend', 'mousedown', 'mouseup']) f.addEventListener(ev, eat, true);
  }
  // (the codes: for now, one)
