  // (several things at once: the box round all of them -- a title and its row of buttons, say)
  function tutUnion(ids){
    return { rect(){
      let l = Infinity, t = Infinity, r = -Infinity, b = -Infinity;
      for(const id of ids){
        let e = document.getElementById(id); if(!e) continue;
        if(e.tagName === 'BUTTON' && e.parentNode && e.parentNode.classList.contains('opt-row')) e = e.parentNode;
        const q = e.getBoundingClientRect(); l = Math.min(l, q.left); t = Math.min(t, q.top); r = Math.max(r, q.right); b = Math.max(b, q.bottom);
      }
      return { left:l, top:t, right:r, bottom:b, width:r - l, height:b - t };
    } };
  }
  // (the card goes on whichever side of the highlighted thing has more room, clear of it)
  function tutCardBeside(b){
    // near the bottom of the screen; above the highlighted thing only when that is down there itself
    const gap = 14, margin = Math.max(16, innerHeight*0.04), h = tutCard.offsetHeight || 180;
    tutCard.style.maxHeight = 'none';
    if(b.bottom + gap + h <= innerHeight - margin){ tutCard.style.top = 'auto'; tutCard.style.bottom = margin + 'px'; }
    else {
      const bottom = Math.min(innerHeight - b.top + gap, innerHeight - h - margin);   // (never off the top)
      tutCard.style.top = 'auto'; tutCard.style.bottom = Math.max(margin, bottom) + 'px';
    }
  }
