  function bindActivate(el, handler){
    let firedAt = 0;
    const fire = ()=>{
      const now = Date.now();
      if(now - firedAt < 500) return; // guard against click firing right after touchend
      firedAt = now;
      SFX.unlock();                                               // any tap can start the audio (browser rule)
      if(el.classList && el.classList.contains('render-opt')) SFX.fx('click');
      handler();
    };
    el.addEventListener('click', fire);
    el.addEventListener('touchend', (e)=>{ e.preventDefault(); fire(); }, {passive:false});
  }
  bindActivate(document.getElementById('mode-maw'), ()=>{ if(modeGate('maw')) startGame('maw'); });
