  const ACH_RACE = { rep25:'raider', rep250:'raider', man10:'trappist', man100:'trappist', zeta25:'alien', zeta250:'alien', beast1:'android' };
  const achShown = a => !ACH_RACE[a.id] || raceMet(ACH_RACE[a.id]);
  // (pilot-section ids are prefixed so they never clash with the campaign's)
  for(const a of ACH) if(a.cat === 'PILOT') a.id = 'p_' + a.id;
  function achCheck(){
    const r = recData(); let got = 0;
    for(let pass = 0; pass < 2; pass++)                   // (twice: the achievement-count ones see this round's)
      for(const a of ACH){
        if(r.ach[a.id]) continue;
        let c = 0; try { c = a.cur(); } catch(e){}
        if(c >= a.goal){ r.ach[a.id] = Date.now(); got++; banner('ACHIEVEMENT', a.name.toUpperCase()); }
      }
    if(got) progSave();
  }

  // ---------- the three pages Player Options opens (each a window of its own over the menu) ----------
  const esc = t => String(t).replace(/[&<>"]/g, c => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;' })[c]);
  const fmtN = n => Math.floor(n || 0).toLocaleString();
  function plOpen(id){ SFX.fx('click'); nameDone(true); playerDialog.style.display = 'none'; document.getElementById(id).style.display = 'flex'; }
  function plClose(id){ SFX.fx('click'); document.getElementById(id).style.display = 'none'; playerDialog.style.display = 'flex'; pilotRefresh(); }
  for(const id of ['ach-page', 'rec-page', 'ency-page']){
    bindActivate(document.getElementById(id + '-back'), ()=>plClose(id));
  }
  function achRender(){
    achCheck();
    const r = recData(), SHOWN = ACH.filter(achShown), have = SHOWN.filter(a => r.ach[a.id]).length;
    document.getElementById('ach-count').textContent = have + ' / ' + SHOWN.length + ' unlocked';
    let h = '', cat = '';
    for(const a of SHOWN){
      if(a.cat !== cat){ cat = a.cat; h += '<div class="pl-sec">' + cat + '</div>'; }
      let c = 0; try { c = a.cur(); } catch(e){}
      const done = !!r.ach[a.id], f = Math.max(0, Math.min(1, c/a.goal));
      h += '<div class="ach-row' + (done ? ' done' : '') + '"><div class="ach-mark">' + (done ? '&#10003;' : '') + '</div><div class="ach-txt"><b>' + esc(a.name) + '</b><span>' + esc(a.desc) + '</span>'
        + (done ? '<i>unlocked ' + new Date(r.ach[a.id]).toLocaleDateString(undefined, { year:'numeric', month:'short', day:'numeric' }) + '</i>'
          : a.goal > 1 ? '<div class="ach-bar"><div style="width:' + (f*100).toFixed(1) + '%"></div></div><i>' + fmtN(Math.min(c, a.goal)) + ' / ' + fmtN(a.goal) + '</i>' : '')
        + '</div></div>';
    }
    document.getElementById('ach-list').innerHTML = h;
  }
  function recSections(){
    const r = recData(), P = pilotData();
    const side = ({ human:'Human', alien:'Zeta', trappist:'Manti', raider:'Repti', android:'Android' })[prog.faction] || 'none yet';
    const S = [
      ['PILOT', [['Name', P.name], ['Licence issued', new Date(P.issued).toLocaleDateString(undefined, { year:'numeric', month:'short', day:'numeric' })], ['Faction', side],
        ['Achievements', Object.keys(r.ach).length + ' / ' + ACH.length], ['Stardust now', fmtN(prog.dust)], ['Dark matter now', fmtN(prog.dm)], ['Stardust earned', fmtN(r.dust)]]],
      ['TIME PLAYED', [['In all', fmtTime(sumOf(r.t))], ['Blackhole', fmtTime(r.t.maw)], ['Ship', fmtTime(r.t.ship)], ['Earth', fmtTime(r.t.earth)], ['Universe', fmtTime(r.t.universe)], ['Watching the computer', fmtTime(r.t.computer)]]],
      ['GAMES STARTED', [['In all', fmtN(sumOf(r.games))], ['Blackhole', fmtN(r.games.maw)], ['Ship', fmtN(r.games.ship)], ['Earth', fmtN(r.games.earth)], ['Universe', fmtN(r.games.universe)], ['Computer', fmtN(r.games.computer)]]],
      ['BLACKHOLE', [['Universes devoured', fmtN(r.devoured)], ['Fastest', r.best ? fmtTime(r.best) : '-'], ['Swallowed in all', fmtN(sumOf(r.eat))],
        ['Asteroids', fmtN(r.eat.asteroid)], ['Comets', fmtN(r.eat.comet)], ['Space debris', fmtN(r.eat.junk)], ['Moons', fmtN(r.eat.moon)], ['Planets', fmtN(r.eat.planet)], ['Stars', fmtN(r.eat.star)],
        ['Neutron stars', fmtN(r.eat.violetdwarf)], ['Black holes', fmtN(r.eat.blackhole)], ['Quasars', fmtN(r.eat.quasar)], ['Ultramassive black holes', fmtN(r.eat.universe)]]],
      ['COMBAT', [['Ships taken down', fmtN(r.kills)], ['Captured with EXTRACT', fmtN(r.taken)], ['Human', fmtN(r.race.human)]].concat([['Zeta', 'alien'], ['Repti', 'raider'], ['Manti', 'trappist'], ['Android', 'android']].filter(x => raceMet(x[1])).map(x => [x[0], fmtN(r.race[x[1]])])).concat([
        ['Lone hunters', fmtN(r.race.lone)], ['Civilian shuttles', fmtN(r.race.civil)], ['Capital-class ships', fmtN(r.caps)], ['Laser shots fired', fmtN(r.shots)], ['Boosts', fmtN(r.boosts)], ['Ships lost (deaths)', fmtN(r.deaths)]])],
      ['MINING', [['Small bodies shot apart', fmtN(sumOf(r.shot))], ['Asteroids', fmtN(r.shot.asteroid)], ['Comets', fmtN(r.shot.comet)], ['Debris', fmtN(r.shot.junk)], ['Wrecks harvested', fmtN(r.wrecks)],
        ['Mined from small moons', fmtN(r.moonRes)], ['Resources gathered', fmtN(r.res)], ['Resources banked', fmtN(r.banked)], ['Times docked', fmtN(r.docks)]]],
      ['CAMPAIGN', [['Worlds settled', fmtN(r.settled)], ['Tier 1 ships built', fmtN(r.built[0])], ['Tier 2 ships built', fmtN(r.built[1])], ['Tier 3 ships built', fmtN(r.built[2])]]],
      ['EXPLORATION', [['Levels reached', Object.keys(r.tiers).length + ' / 9'], ['Close-up visits', fmtN(r.visits)], ['Different bodies seen close up', fmtN(r.seen.length)]]],
    ];
    return S;
  }
  function recRender(){
    const S = recSections();
    document.getElementById('rec-list').innerHTML = S.map(([t, rows]) => '<div class="pl-sec">' + t + '</div>' + rows.map(([a, b]) => '<div class="rec-row"><span>' + esc(a) + '</span><b>' + esc(b) + '</b></div>').join('')).join('');
  }
  let encyCat = 0, encyItem = 0;
  // (YOUR SHIPS and ENEMY SHIPS: from each ship's own stats and actions)
  const ENCY_RACE_NAME = { human:'Human', alien:'Zeta', trappist:'Manti', raider:'Repti', android:'Android', lone:'Lone hunter' };
  const ENCY_GET = { scout:'Your first ship.', gunner:'Build a Tier 2, or buy it in the Store.', fleet:'Build a Tier 3, or buy it in the Store.',
    jumper:'Yours when you first meet the Zetas.', saucer:'Build a Tier 2 as a Zeta, or buy it in the Store.', mothership:'Build a Tier 3 as a Zeta, or buy it in the Store.',
    tpriest:'Yours when you first meet the Manti.', thunter:'Build a Tier 2 as a Manti, or buy it in the Store.', twarrior:'Build a Tier 3 as a Manti, or buy it in the Store.',
    twarlock:'Buy it in the Store.', tmage:'Buy it in the Store.', trogue:'Buy it in the Store.', tmonk:'Buy it in the Store.', tpaladin:'Buy it in the Store.',
    rblaster:'Take down ten Repti ships, or buy it in the Store.', rmother:'Fly a Blaster for five minutes, or buy it in the Store.' };
  const ENCY_THEIRS = [['jammer', 'human', 'Shuttle', 'Civilian traffic. It never fights, and human ships can\u2019t harm it.'],
    ['outlaw', 'lone', 'Blitzer', 'Hunts alone, out between the galaxies, and attacks anyone.'], ['rogue', 'lone', 'Stalker', 'Hunts alone and keeps slipping out of sight.'],
    ['courier', 'trappist', 'Priest', 'The commonest Manti hull. Destroying one patches your hull from its cargo.'], ['warlock', 'trappist', 'Warlock', 'A Priest turned to raiding.'],
    ['warrior', 'trappist', 'Warrior', 'Armed for a fight; leads the swarms.'], ['rmage', 'trappist', 'Mage', 'Refitted with long guns.'], ['rrogue', 'trappist', 'Rogue', 'A fast striker that hits and runs.'],
    ['rmonk', 'trappist', 'Monk', 'A heavy hull that mends its own.'], ['rpaladin', 'trappist', 'Paladin', 'An armoured escort.'], ['hunter', 'trappist', 'Hunter', 'A Priest refitted as a gunship.'],
    ['rblaster', 'raider', 'Blaster', 'Repti raid in groups of Blasters.'], ['rmother', 'raider', 'Repti Broodship', 'The Repti fleet command, leading their raids.'],
    ['blitzer', 'android', 'Jammer', 'An Android scout: its hits jam your laser for a moment.'], ['outlaw2', 'android', 'Outlaw', 'An Android gunship.'],
    ['hawk', 'android', 'Hawk', 'An Android strike ship.'], ['beast', 'android', 'Beast', 'The Android fleet command, holding back and pounding you from range.']];
  function encyActs(k){ const A = shipActs(k); if(!A) return ''; const L = a => (ACT_INFO[a] || { l:a.toUpperCase() }).l; return (A.L.length ? 'Left: ' + A.L.map(L).join(', ') + '. ' : '') + (A.R.length ? 'Right: ' + A.R.map(L).join(', ') + '.' : ''); }
  function encyStats(k){
    const S = shipStat(k); if(!S) return '';
    const n = x => (Math.round(x*100)/100).toLocaleString();
    return 'Hull ' + n(S.hp) + ', armour ' + n(S.armour) + '%, speed ' + n(S.speed) + 'x, size ' + n(S.size) + '. ' + (S.dmg > 0 ? 'Hits for ' + n(S.dmg) + ' every ' + n(S.rof) + ' s.' : 'Unarmed.');
  }
  function encyMine(){
    const cls = { small:'small', medium:'medium', large:'capital class' };
    return Object.keys(SHIP_MODELS).filter(k => SHIP_MODELS[k].side === 'human' || raceMet(SHIP_MODELS[k].side)).map(k => {
      const M = SHIP_MODELS[k], S = shipStat(k) || {};
      return { n:M.label.charAt(0) + M.label.slice(1).toLowerCase(), ic:'s_' + k, t:ENCY_RACE_NAME[M.side] + ', ' + cls[M.cls] + '. ' + encyStats(k) + (S.cargo ? ' Hold: ' + S.cargo + ' of each resource.' : '') + '\n' + encyActs(k) + '\n' + (ENCY_GET[k] || '') };
    });
  }
  function encyTheirs(){
    const mine = SHIP_MODELS[shipModel] && shipOpen(shipModel) && (SHIP_MODELS[shipModel].side === 'human' || raceMet(SHIP_MODELS[shipModel].side)) ? shipModel : 'scout';
    const yours = shipStat(mine), hit = yours && yours.dmg > 0 ? yours.dmg : 0;
    return ENCY_THEIRS.filter(([, r]) => r === 'human' || r === 'lone' || raceMet(r)).map(([k, r, nm, w]) => {
      const S = shipStat(k) || {}, hits = hit && S.hp ? Math.ceil(S.hp/armourCut(hit, S.armour)) : 0;
      return { n:nm, ic:'e_' + k, t:ENCY_RACE_NAME[r] + '. ' + w + '\n' + encyStats(k) + '\n' + encyActs(k) + (hits ? '\nAbout ' + hits + ' hits from your ' + SHIP_MODELS[mine].label.toLowerCase() + '\u2019s guns.' : '') };
    });
  }
  function encyView(){                                       // (the book as you know it: no race you haven't met)
    return ENCY.map(c => ({ cat:c.cat, items:c.gen === 'mine' ? encyMine() : c.gen === 'theirs' ? encyTheirs() : c.items.filter(it => (!ENCY_RACE[it.n] || raceMet(ENCY_RACE[it.n])) && (!it.any || it.any.some(raceMet)))
      .map(it => typeof it.t === 'function' ? { n:it.n, t:it.t() } : it) })).filter(c => c.items.length);
  }
  function encyRender(){
    const EV = encyView(), C = EV[encyCat] || EV[0], I = C.items[encyItem] || C.items[0];
    document.getElementById('ency-cats').innerHTML = EV.map((c, i) => '<button class="ency-b' + (i === encyCat ? ' on' : '') + '" data-c="' + i + '">' + esc(c.cat) + '</button>').join('');
    document.getElementById('ency-items').innerHTML = C.items.map((it, i) => '<button class="ency-b' + (i === encyItem ? ' on' : '') + '" data-i="' + i + '">' + esc(it.n) + '</button>').join('');
    document.getElementById('ency-text').innerHTML = '<h3>' + esc(I.n) + '</h3>' + I.t.split('\n').map(p => '<p>' + esc(p) + '</p>').join('');
    document.getElementById('ency-text').scrollTop = 0;
  }
  function encyTap(e){
    const b = e.target.closest && e.target.closest('.ency-b'); if(!b) return;
    SFX.fx('click');
    if(b.dataset.c !== undefined){ encyCat = +b.dataset.c; encyItem = 0; encyRender(); document.getElementById('ency-items').scrollTop = 0; }
    else { encyItem = +b.dataset.i; encyRender(); }
  }
  document.getElementById('ency-cats').addEventListener('click', encyTap);
  document.getElementById('ency-items').addEventListener('click', encyTap);
