    TAB.open = true; TAB.ctx = ctx; TAB.stack = [{ v:'root' }]; TAB.sel = 0; TAB.msg = '';
    const src = TAB.src = tabSrc(ctx), b = src.getBoundingClientRect(), f = tabFinal();
    for(const e of tabFly.querySelectorAll('.tf-name')) e.textContent = pilotData().name;
    tabRender();
