    if(instant || b.width < 2){ tabPlace(f, -180, 16); tabFly.classList.add('ready'); tabDim.classList.add('on'); pilotRefresh(); tabFit(); return; }
    tabPlace(b, 0, b.width*0.078);
    void tabFly.offsetWidth;
    tabFly.classList.add('anim'); tabDim.classList.add('on'); tabPlace(f, -180, 16); SND(37, 1, 0);
