    tabFly.classList.remove('ready'); tabDim.classList.remove('on');
    TAB.done = ()=>{ TAB.done = null; tabFly.style.display = 'none'; tabDim.style.display = 'none'; tabFly.classList.remove('anim'); if(src) src.style.visibility = ''; };
    if(instant || !b || b.width < 2){ TAB.done(); return; }
