    hangarName.style.display = three ? 'none' : ''; hangarSub.style.display = three ? 'none' : '';
    hangarHint.style.display = ship && !three && renderMode !== '3d' ? 'block' : 'none';
    if(three){ spinCv.style.display = 'none'; spinView.on = false; hangar3DModel(); buildPartRow(); }
    if(!ship){ spinCv.style.display = 'none'; spinView.on = false; }
    hangarPick.style.display = ship ? 'flex' : 'none';
    hangarName.textContent = ship ? SHIP_MODELS[shipModel].label : 'Spaghettify';
    hangarSub.textContent = ship ? ({ trappist:'manti', alien:'zeta', human:'human', raider:'repti' })[SHIP_MODELS[shipModel].side] + ' · ' + SHIP_CLASS[SHIP_MODELS[shipModel].cls].words : 'choose its colour';
    const hs = document.getElementById('hangar-stats'), sc = SHIP_CLASS[SHIP_MODELS[shipModel].cls];
    hs.style.display = 'none';                                       // (the numbers live in the viewer box now)
    { const st = document.getElementById('hangar-stage'), L = document.getElementById('hv-l'), R = document.getElementById('hv-r'), S = shipStat(shipModel), A = shipActs(shipModel);
      const on = ship && !!S; st.classList.toggle('hv-on', on); L.style.display = R.style.display = on ? 'flex' : 'none';
      if(on){
        const n = x => (Math.round(x*10)/10).toLocaleString(), row = (k, v) => '<div>' + k + '</div><div class="hv-v">' + v + '</div>';
        L.innerHTML = row('ATTACK', S.dmg > 0 ? n(S.dmg) + ' / ' + n(S.rof) + 's' : '-') + row('HEALTH', n(S.hp)) + row('ARMOR', n(S.armour) + '%');
        const nm = { laserL:'LASER L', laserR:'LASER R' }, acts = A ? A.L.concat(A.R) : [];
        R.innerHTML = '<div>ABILITIES</div>' + acts.map(a => '<div class="hv-a">' + (nm[a] || (ACT_INFO[a] ? ACT_INFO[a].l : a.toUpperCase())) + '</div>').join('');
      }
    }
    if(ship){
      const pip = (name, k) => '<span><b>' + name + '</b><span class="pip">' + '■'.repeat(k) + '<i>' + '■'.repeat(3 - k) + '</i></span></span>';
      hs.innerHTML = pip('ARMOR', sc.pips[0]) + pip('ATTACK', sc.pips[1]) + pip('SPEED', sc.pips[2]) + '<span class="ab">' + sc.ability.toUpperCase() + '</span>';
    }
    for(const k in hangarOpts) hangarOpts[k].classList.toggle('active', k === shipModel);
    document.getElementById('hangar-stage').setAttribute('data-cls', SHIP_MODELS[shipModel].cls);
