  let previewKey = null, previewRunning = false, previewLast = 0;
  function previewSwirlFor(rgb){
    const k = (rgb ? rgb.join('.') : 'orig') + '|' + holeAdjKey(); if(k === previewKey) return;
    previewKey = k; holePixels(rgb, id => { if(previewKey === k) previewSwirl.src = id; });
  }
  function placeSwirlCanvas(){
    if(!swirlCanvas || !holeImg.getBoundingClientRect) return;
    const st = document.getElementById('hangar-stage').getBoundingClientRect(), b = holeImg.getBoundingClientRect();
    const k = Math.min(b.width/480, b.height/262), w = 480*k, h = 262*k;
    swirlCanvas.style.left = (b.left - st.left + (b.width - w)/2) + 'px'; swirlCanvas.style.top = (b.top - st.top + (b.height - h)/2) + 'px';
    swirlCanvas.style.width = w + 'px'; swirlCanvas.style.height = h + 'px';
  }
