  const zoneDivider = document.getElementById('zone-divider');
  let hintFaded = false;
  function fadeHint(){ if(!hintFaded){ hint.style.opacity='0'; zoneDivider.style.opacity='0'; hintFaded=true; } }

  function zoneOf(clientX){
    if(earthLike()) return 'look'; // whole screen is look-around in Earth mode (and on a home world)
    return clientX < window.innerWidth/2 ? 'move' : 'look';
  }
