    const name = K.name || (side === 'alien' ? 'Zeta ' : side === 'human' ? 'Human ' : '') + lab.charAt(0) + lab.slice(1).toLowerCase();
    const desc = K.desc || (side === 'alien' ? 'a zeta warship' : 'a human warship');
