    set('fl-plist', f.planets ? PLANET_NAMES[side].slice(0, f.planets).join(' · ') : 'no planets left');
    set('fl-t1', f.fleet[0]); set('fl-t2', f.fleet[1]); set('fl-t3', f.fleet[2]);
    set('fl-n1', W[0] + 's'); set('fl-n2', W[1] + 's'); set('fl-n3', W[2] + 's');
    const full = f.planets >= PLANET_NAMES[side].length, cc = colonizeCost(f);
    set('fl-d0', full ? 'every world settled' : PLANET_NAMES[side][f.planets].toLowerCase() + ' · ' + cc);
