      row('banked', resFmt(resBank(f, side)) || '0'); row('planets', f.planets);
      row(W[0] + 's · ' + W[1] + 's · ' + W[2] + 's', f.fleet[0] + ' · ' + f.fleet[1] + ' · ' + f.fleet[2]);
