      if(shipCanDestroy(rayTarget)) hurtBody(rayTarget, RAY_DPS*dt); else tooBigNote(rayTarget);
      if((raySound -= dt) <= 0){ SFX.fx('crackle'); raySound = 0.45; }
      const sp = hole.radius*14;                                  // sparks where it hits
